steps.snippet:
location = binding.get("location")
if not location:
    raise ValueError("Missing binding value 'location'")

idx = device.find(hint="Type to search all", editable=True)
if idx is None:
    idx = device.find(text="Type to search all", editable=True)

if idx is None:
    for i, el in enumerate(device.elements()):
        if el.get("editable") and el.get("class_name") == "EditText":
            label = f"{el.get('text') or ''} {el.get('hint') or ''}".lower()
            if "search" in label:
                idx = i
                break

if idx is None:
    raise LookupError("Could not find OsmAnd search EditText")

device.input_text(str(location), index=idx)
device.settle(0.5)

search_idx = device.find(hint='Type to search all', editable=True, clickable=True)
if search_idx is None:
    raise RuntimeError('OsmAnd search field not found')

clear_idx = device.find(description='Clear', clickable=True)
if clear_idx is None:
    clear_idx = device.find(text='Clear', clickable=True)
if clear_idx is not None:
    device.click(index=clear_idx)
else:
    device.long_press(index=search_idx)

device.input_text(binding['location'], index=search_idx)

loc = binding.get("location")
if not loc:
    raise ValueError("binding missing location")

idx = device.find(text=loc, editable=False)
if idx is None:
    idx = device.find(contains=loc, editable=False)
if idx is None:
    idx = device.find(contains="°", editable=False)
if idx is None:
    raise LookupError(f"No search result found for {loc!r}")

device.click(index=idx)
device.settle(2)

idx = device.find(editable=True, contains='Search')
if idx is None:
    idx = device.find(editable=True, contains='search')
if idx is None:
    idx = device.find(editable=True, clickable=True)
if idx is None:
    raise ValueError('OsmAnd search EditText not found')
device.input_text(binding['location'], index=idx)

loc = binding.get('location') or binding.get('query') or binding.get('coordinate')
if not loc:
    raise ValueError('binding must contain location/query/coordinate')

for query in (
    {'text': loc, 'editable': False},
    {'contains': loc, 'editable': False},
    {'contains': '°', 'editable': False},
    {'contains': 'N,', 'editable': False},
    {'contains': 'E,', 'editable': False},
):
    idx = device.find(**query)
    if idx is not None:
        device.click(index=idx)
        break
else:
    raise RuntimeError(f'Could not find search result for {loc!r}')

location = binding.get("location")
if not location:
    raise RuntimeError("binding['location'] is required")

idx = device.find(hint="Type to search all", editable=True)
if idx is None:
    idx = device.find(text="Type to search all", editable=True)
if idx is None:
    raise RuntimeError("OsmAnd search EditText not found")

device.input_text(str(location), index=idx)

marker_idx = None
for i, el in enumerate(device.elements()):
    if el.get("text") == "Marker" and el.get("class_name") == "TextView":
        marker_idx = el.get("index", i)
        break

if marker_idx is None:
    marker_idx = device.find(text="Marker")

if marker_idx is None:
    raise RuntimeError("Could not find the 'Marker' context menu item")

device.click(index=marker_idx)
device.settle(1.0)
